def semver_sort(versions):
    def parse_prerelease_id(ident):
        if ident.isdigit():
            return (0, int(ident))
        else:
            return (1, ident)

    def make_key(v):
        # strip build metadata
        main_part = v.split('+', 1)[0]
        # find prerelease part: first '-' in main_part
        if '-' in main_part:
            idx = main_part.index('-')
            core = main_part[:idx]
            prerelease = main_part[idx+1:]
        else:
            core = main_part
            prerelease = None

        major_str, minor_str, patch_str = core.split('.')
        major, minor, patch = int(major_str), int(minor_str), int(patch_str)

        if prerelease is None:
            has_pre_flag = 1  # no prerelease sorts after
            pre_tuple = ()
        else:
            has_pre_flag = 0
            idents = prerelease.split('.')
            pre_tuple = tuple(parse_prerelease_id(i) for i in idents)

        return (major, minor, patch, has_pre_flag, pre_tuple)

    return sorted(versions, key=make_key)

